using System;
using System.Collections.Generic;
using UnityEngine;
namespace GreyHarbor {
 public sealed partial class RaidGame {
  public RaidInventory Safe=new RaidInventory(2,2);public ItemStack RigGear,PackGear,Helmet,Armor,SecondWeapon;
  internal ItemArea healArea=ItemArea.Rig,reloadArea=ItemArea.Rig;internal string healId,reloadId;
  void CaptureGear(){Save.SafeItems=Safe.Snapshot();Save.RigGear=RaidInventory.Copy(RigGear);Save.PackGear=RaidInventory.Copy(PackGear);Save.Helmet=RaidInventory.Copy(Helmet);Save.Armor=RaidInventory.Copy(Armor);Save.SecondWeapon=RaidInventory.Copy(SecondWeapon);}
  void RestoreGear(){Safe=new RaidInventory(2,Save.Npc319.SafeRows);Safe.Restore(Save.SafeItems);RigGear=RaidInventory.Copy(Save.RigGear);PackGear=RaidInventory.Copy(Save.PackGear);Helmet=RaidInventory.Copy(Save.Helmet);Armor=RaidInventory.Copy(Save.Armor);SecondWeapon=RaidInventory.Copy(Save.SecondWeapon);}
  void CertifyGear(){foreach(var p in new[]{RigGear,PackGear,Helmet,Armor,SecondWeapon})if(p!=null){Certification319.Normalize(p);if(WeaponRules279.IsWeapon(p.Kind))p.LoadedFound314=p.Loaded314;}}
  void ResetRaidFound(){foreach(var inv in new[]{Chest,Bag,Safe})foreach(var p in inv.Slots){p.RaidFound=false;ModRules30.ClearFound(p);}foreach(var p in new[]{Equipped,SecondWeapon,Helmet,Armor,RigGear,PackGear})if(p!=null){p.RaidFound=false;ModRules30.ClearFound(p);}}
  public int RaidGain {get {int n=Chest.FoundValue+Bag.FoundValue+Safe.FoundValue;foreach(var p in new[]{Equipped,SecondWeapon,Helmet,Armor,RigGear,PackGear})if(p!=null)n+=WeaponRules279.IsWeapon(p.Kind)?ModRules30.FoundValue(p):p.RaidFound?RaidInventory.Value(p):0;return n;}}
  public ItemStack GearAt(ItemArea a){switch(a){case ItemArea.Weapon:return Equipped;case ItemArea.SecondWeapon:return SecondWeapon;case ItemArea.Head:return null;case ItemArea.Armor:return Armor;case ItemArea.RigEquipment:return RigGear;case ItemArea.PackEquipment:return PackGear;default:return null;}}
  void SetGear(ItemArea a,ItemStack item){switch(a){case ItemArea.Weapon:StoreActiveMagazine314();Equipped=item;RestoreActiveMagazine314();break;case ItemArea.SecondWeapon:SecondWeapon=item;break;case ItemArea.Head:Helmet=item;break;case ItemArea.Armor:Armor=item;break;case ItemArea.RigEquipment:RigGear=item;Chest=RaidInventory.Container(item,true);break;case ItemArea.PackEquipment:PackGear=item;Bag=RaidInventory.Container(item,false);break;}}
  static bool IsGearArea(ItemArea a)=>a==ItemArea.Weapon||a==ItemArea.SecondWeapon||a==ItemArea.Head||a==ItemArea.Armor||a==ItemArea.RigEquipment||a==ItemArea.PackEquipment;
  static bool GearFits(ItemArea a,ItemKind k)=>a==ItemArea.Weapon||a==ItemArea.SecondWeapon?WeaponRules279.IsWeapon(k):a==ItemArea.Head?false:a==ItemArea.Armor?RaidInventory.IsArmor(k):a==ItemArea.RigEquipment?RaidInventory.IsRig(k):a==ItemArea.PackEquipment&&RaidInventory.IsPack(k);
  void InitializeLootGrids(){int i=0;var random=new System.Random();foreach(var box in Map.Loot){if(!Map.IsHarbor&&!Map.ExteriorPreview&&!Map.IsInterior&&!Map.AssetShowcase2717){box.Type=(SupplyType)(i++%6);box.Tier=LootBalance.TierFor(box.Type);box.Name=HarborContent.SupplyNames[(int)box.Type];box.SearchDuration=HarborContent.SearchSeconds(box.Type);box.Items.Clear();box.Items.AddRange(HarborContent.Contents(box.Type,random,ActiveHardMode,box.Tier));}foreach(var p in box.Items){p.Origin=Certification319.Collection(p.Kind)?ItemOrigin.Pending:ItemOrigin.Ordinary;p.Cell=-1;p.RaidFound=true;p.Identified=false;}EnsureLootGrid(box);}}
  public RaidInventory EnsureLootGrid(LootContainer box){if(box==null)return null;foreach(var item in box.Items){Certification319.Normalize(item);if(Phase==GamePhase.Raid&&!box.PlayerDrop314&&Certification319.Collection(item.Kind))item.Origin=ItemOrigin.Pending;}if(box.Corpse325!=null&&!box.Corpse325.Soldier)return CorpseLoot325.FixedGrid(box.Corpse325.BioColumns,box.Corpse325.BioRows,box.Items);var g=new RaidInventory(6,Math.Max(5,box.GridRows));var snapshot=new List<ItemStack>(box.Items);bool valid=true;foreach(var p in snapshot){if(p==null||p.Count<=0||p.Count>RaidInventory.Limit(p.Kind)||!g.Fits(p,p.Cell)){valid=false;break;}g.Slots.Add(p);}if(valid)return new RaidInventory(6,g.Rows,box.Items);g=new RaidInventory(6,Math.Max(5,box.GridRows));snapshot.RemoveAll(p=>p==null||p.Count<=0);while(true){try{g.Restore(snapshot);break;}catch(InvalidOperationException){box.GridRows=Math.Max(5,box.GridRows)+5;g=new RaidInventory(6,box.GridRows);}}box.Items.Clear();box.Items.AddRange(g.Snapshot());return new RaidInventory(6,g.Rows,box.Items);}
  void OnApplicationQuit(){if(IsLoading2721)return;ResetOptionalFeatures2761();if(TrainingActive)return;if(Phase==GamePhase.Base){CaptureCarry();CaptureDrops();WriteSave();}else if(Phase==GamePhase.Raid){Save.SafeItems=Safe.Snapshot();WriteSave();}}
  public bool SortWarehouse()=>CampChange(()=>{if(Panel!=CampPanel.Warehouse)return false;var grid=CampRules.Grid(Save);var packed=new RaidInventory(grid.Columns,grid.Rows,true);if(!packed.Repack(grid.Snapshot()))return false;Save.Warehouse=packed.Snapshot();return true;},"仓库已整理，数量与认证保持不变。");
  public bool SellWarehouse(HashSet<string> ids){return CampChange(()=>{if(ids==null||ids.Count==0||!(Panel==CampPanel.Warehouse||Panel==CampPanel.Market&&InventoryOpen&&Vector3.Distance(Player.transform.position,RaidMap.Market)<2))return false;int amount=0;var selected=Save.Warehouse.FindAll(p=>ids.Contains(p.Id));if(selected.Count!=ids.Count)return false;foreach(var p in selected)amount=checked(amount+p.Count*RaidInventory.Value(p));Save.Coins=checked(Save.Coins+amount);TradeRecord.Append(Save,false,amount,selected);Save.Warehouse.RemoveAll(p=>ids.Contains(p.Id));return true;},"所选物资已出售，金币已存入。");}
 }
}
